#!/usr/bin/env node
/**
 * Builds the self-contained bundle the managed package channels install.
 *
 *   node scripts/build-bundle.mjs --out dist-bundle
 *
 * Homebrew, Scoop and Chocolatey each unpack this archive and shim the launcher
 * inside it. They do not run `npm install`, and that is the point: seven of the
 * eight runtime dependencies are `^` ranges and the npm tarball ships no
 * dependency tree, so every `npm install` resolves versions afresh on the user's
 * machine. Resolving once here means the three managed channels install bytes a
 * release actually tested, identical on every machine (D2).
 *
 * Three properties this script is responsible for, each of which has to be
 * proved rather than assumed:
 *
 *   - It is *complete*. npm creates the `looptroop` command at install time, so
 *     an unpacked bundle has no executable at all unless one is generated here.
 *   - It is *portable*. It is built once on Linux and unpacked on macOS and
 *     Windows, so a compiled addon, a platform-gated package or an install
 *     script would produce a bundle that installs and then does not run.
 *   - It is *reproducible*. Two builds of one commit must be byte-identical, or
 *     "the hash in the formula matches the release" stops meaning anything.
 */
import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import {
  chmodSync, copyFileSync, cpSync, existsSync, mkdirSync, mkdtempSync,
  readFileSync, readdirSync, rmSync, statSync, utimesSync, writeFileSync,
} from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join, relative, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..')

/** Everything the bundle carries besides `node_modules` and the generated `bin`. */
const STAGED = ['dist', 'package.json', 'package-lock.json', 'LICENSE', 'THIRD-PARTY-NOTICES.md', 'README.md', 'CHANGELOG.md']

/**
 * A fixed date for every entry. Real mtimes differ between two checkouts of the
 * same commit, which alone would make the archive unreproducible. 1980-01-01
 * because it is the earliest a zip can represent, in case a channel ever wants
 * one of those instead.
 */
const FIXED_MTIME = 315_532_800

function fail(message, ...detail) {
  process.stderr.write(`\nFAIL: ${message}\n`)
  for (const line of detail) process.stderr.write(`  ${line}\n`)
  process.stderr.write('\n')
  process.exit(1)
}

function run(command, args, cwd) {
  return execFileSync(command, args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'inherit'] })
}

function walk(dir, onEntry) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name)
    onEntry(full, entry)
    if (entry.isDirectory()) walk(full, onEntry)
  }
}

// --- the executables npm would otherwise have created ----------------------

/**
 * `bin` entries in package.json are instructions to npm, not files: npm writes
 * the shim when it installs, and the published tarball contains no `bin/` at
 * all. A channel that unpacks an archive gets no such favour, so the three
 * shapes of executable a user might invoke are written here.
 *
 * Each one runs Node against the real launcher rather than reimplementing it,
 * so everything the launcher does — the old-Node message above all — still
 * happens exactly once, in one place.
 */
const LAUNCHER = 'dist/server/cli/launcher.cjs'

const WRAPPERS = {
  // Symlink-following because `brew link` and a hand-made `ln -s` into
  // ~/.local/bin both make `$0` a link, and `dirname $0` would then resolve to
  // the link's directory, where there is no `dist/`.
  looptroop: `#!/bin/sh
# Generated by scripts/build-bundle.mjs. Do not edit.
target=$0
while [ -L "$target" ]; do
  link=$(readlink "$target")
  case $link in
    /*) target=$link ;;
    *) target=$(dirname -- "$target")/$link ;;
  esac
done
root=$(CDPATH= cd -- "$(dirname -- "$target")/.." && pwd -P)
exec node "$root/${LAUNCHER}" "$@"
`,
  // What Scoop's shim and Chocolatey's Install-BinFile point at: a `#!` script
  // cannot be shimmed on Windows.
  'looptroop.cmd': `@echo off\r
setlocal\r
node "%~dp0..\\${LAUNCHER.replaceAll('/', '\\\\')}" %*\r
exit /b %ERRORLEVEL%\r
`,
  'looptroop.ps1': `#!/usr/bin/env pwsh
# Generated by scripts/build-bundle.mjs. Do not edit.
& node (Join-Path (Split-Path -Parent $PSScriptRoot) '${LAUNCHER}') @args
exit $LASTEXITCODE
`,
}

// --- gates ------------------------------------------------------------------

/**
 * The staged tree must be the production closure and nothing else.
 *
 * The lockfile's root `dependencies` object names 22 interface packages that
 * belong in `devDependencies`; `npm ci --omit=dev` reads the per-package `dev`
 * flags instead and correctly leaves them out. This is what notices if that
 * ever stops being true and a release quietly starts shipping React.
 */
function assertProductionClosure(stagingDir) {
  const lock = JSON.parse(readFileSync(join(stagingDir, 'package-lock.json'), 'utf8'))
  const manifest = JSON.parse(readFileSync(join(stagingDir, 'package.json'), 'utf8'))
  const devDependencies = new Set(Object.keys(manifest.devDependencies ?? {}))

  const expected = new Set(
    Object.entries(lock.packages ?? {})
      .filter(([path, entry]) => path.startsWith('node_modules/') && entry.dev !== true)
      .map(([path]) => path.replace(/^node_modules\//, '')),
  )

  const installed = new Set()
  const modulesDir = join(stagingDir, 'node_modules')
  for (const entry of readdirSync(modulesDir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue
    if (entry.name.startsWith('@')) {
      for (const scoped of readdirSync(join(modulesDir, entry.name))) installed.add(`${entry.name}/${scoped}`)
    } else {
      installed.add(entry.name)
    }
  }

  const unexpected = [...installed].filter((name) => !expected.has(name)).sort()
  const fromDevDependencies = [...installed].filter((name) => devDependencies.has(name)).sort()

  if (unexpected.length > 0 || fromDevDependencies.length > 0) {
    fail(
      'the staged tree is not the production closure.',
      ...unexpected.map((name) => `not in the lockfile's production set: ${name}`),
      ...fromDevDependencies.map((name) => `a devDependency: ${name}`),
    )
  }

  return installed.size
}

/**
 * Nothing in the bundle may be specific to the machine that built it.
 *
 * The npm-tarball gate (`verify:no-native-addons`) proves the same thing about
 * the package; this proves it about the tree that is actually shipped, which is
 * a different artefact resolved at a different moment.
 */
function assertPortable(stagingDir) {
  const problems = []
  const modulesDir = join(stagingDir, 'node_modules')

  walk(modulesDir, (full, entry) => {
    const shown = relative(stagingDir, full)

    if (entry.isSymbolicLink()) {
      problems.push(`symlink, which does not survive extraction on Windows: ${shown}`)
      return
    }
    if (entry.isFile() && full.endsWith('.node')) {
      problems.push(`compiled addon: ${shown}`)
      return
    }
    if (!entry.isFile() || entry.name !== 'package.json') return

    let packageJson
    try {
      packageJson = JSON.parse(readFileSync(full, 'utf8'))
    } catch {
      return
    }
    const label = `${packageJson.name ?? shown}@${packageJson.version ?? '?'}`

    if (packageJson.os || packageJson.cpu) {
      problems.push(`platform-gated (os=${JSON.stringify(packageJson.os ?? '*')} cpu=${JSON.stringify(packageJson.cpu ?? '*')}): ${label}`)
    }
    for (const script of ['preinstall', 'install', 'postinstall']) {
      if (packageJson.scripts?.[script]) problems.push(`needs an install script never run here (${script}): ${label}`)
    }
    if (packageJson.gypfile === true || existsSync(join(dirname(full), 'binding.gyp'))) {
      problems.push(`compiled via binding.gyp: ${label}`)
    }
  })

  if (problems.length > 0) {
    fail(
      'the bundle would not be portable.',
      ...problems,
      'It is built once on Linux and unpacked on macOS and Windows, so each of these installs and then does not run.',
    )
  }
}

// --- normalisation ----------------------------------------------------------

/** Anything that differs between two builds of the same commit, flattened. */
function normalise(stagingDir) {
  const executable = new Set(Object.keys(WRAPPERS).map((name) => join(stagingDir, 'bin', name)))

  const stamp = (path, isDirectory) => {
    chmodSync(path, isDirectory ? 0o755 : (executable.has(path) ? 0o755 : 0o644))
    utimesSync(path, FIXED_MTIME, FIXED_MTIME)
  }

  walk(stagingDir, (full, entry) => stamp(full, entry.isDirectory()))
  stamp(stagingDir, true)
}

// --- main -------------------------------------------------------------------

const args = process.argv.slice(2)
const outIndex = args.indexOf('--out')
const outDir = resolve(outIndex === -1 ? join(repoRoot, 'dist-bundle') : args[outIndex + 1] ?? fail('--out needs a path'))

const version = JSON.parse(readFileSync(join(repoRoot, 'package.json'), 'utf8')).version
const archiveName = `looptroop-${version}-bundle.tar.gz`
const archivePath = join(outDir, archiveName)

if (!existsSync(join(repoRoot, 'dist', 'server', 'cli', 'launcher.cjs'))) {
  fail('dist/ is missing or incomplete.', 'Run `npm run build` first.')
}

// GNU tar. `--sort` and `--mtime` are not in bsdtar, and without them the
// archive is not reproducible; failing here is better than shipping a bundle
// whose hash changes for no reason.
const tarVersion = run('tar', ['--version']).split('\n')[0] ?? ''
if (!/GNU tar/.test(tarVersion)) fail(`GNU tar is required to build a reproducible archive; found "${tarVersion}".`)

const stagingRoot = mkdtempSync(join(tmpdir(), 'looptroop-bundle-'))
const stagingDir = join(stagingRoot, 'looptroop')

try {
  mkdirSync(stagingDir, { recursive: true })

  for (const item of STAGED) {
    const source = join(repoRoot, item)
    if (!existsSync(source)) fail(`${item} is missing from the checkout, and the bundle needs it.`)
    if (statSync(source).isDirectory()) cpSync(source, join(stagingDir, item), { recursive: true })
    else copyFileSync(source, join(stagingDir, item))
  }

  // `npm ci` refuses to run without a lockfile, which is why one is staged
  // above even though it is of no use to a user.
  process.stdout.write('Resolving production dependencies...\n')
  run('npm', ['ci', '--omit=dev', '--ignore-scripts', '--no-audit', '--no-fund'], stagingDir)

  // Unix symlinks into the packages they point at. Nothing in the bundle
  // executes them — the wrappers below call the launcher directly — and an
  // archive full of symlinks extracts badly on Windows.
  rmSync(join(stagingDir, 'node_modules', '.bin'), { recursive: true, force: true })

  mkdirSync(join(stagingDir, 'bin'))
  for (const [name, contents] of Object.entries(WRAPPERS)) {
    writeFileSync(join(stagingDir, 'bin', name), contents)
  }

  const packageCount = assertProductionClosure(stagingDir)
  assertPortable(stagingDir)
  normalise(stagingDir)

  mkdirSync(outDir, { recursive: true })
  rmSync(archivePath, { force: true })

  // Everything here exists to make two builds of one commit identical: a stable
  // entry order, no owner names, no per-file timestamps beyond the fixed one,
  // no access or change times in the pax headers, and `gzip -n` so the archive
  // name and build time stay out of the gzip header.
  run('tar', [
    '--sort=name',
    `--mtime=@${FIXED_MTIME}`,
    '--owner=0', '--group=0', '--numeric-owner',
    '--format=pax',
    '--pax-option=exthdr.name=%d/PaxHeaders/%f,delete=atime,delete=ctime',
    '--use-compress-program=gzip -9 -n',
    '-cf', archivePath,
    '-C', stagingRoot,
    'looptroop',
  ], repoRoot)

  const bytes = readFileSync(archivePath)
  const sha256 = createHash('sha256').update(bytes).digest('hex')

  process.stdout.write([
    '',
    `bundle      ${archiveName}`,
    `packages    ${packageCount} in node_modules`,
    `bytes       ${bytes.length}`,
    `sha256      ${sha256}`,
    `wrote       ${archivePath}`,
    '',
  ].join('\n'))
} finally {
  rmSync(stagingRoot, { recursive: true, force: true })
}
